C++ syntax with implementation notes:
```c++
class MyClass {
public:
    MyClass(int data) : data_(data) {}
    MyClass(const MyClass& other) : data_(other.data_) { std::cout << "Copy constructor called\n"; }
    MyClass(MyClass&& other) noexcept : data_(other.data_) { other.data_ = 0; std::cout << "Move constructor called\n"; }
    ~MyClass() { std::cout << "Destructor called\n"; }
private:
    int data_;
};

MyClass createMyClass(int data) {
    return MyClass(data); // RVO can be applied here
}

MyClass createMyClass2(int data) {
    MyClass obj(data); 
    return obj; // NRVO can be applied here
}

int main() {
    MyClass obj1 = createMyClass(10);
    MyClass obj2 = createMyClass2(20);
    return 0;
}
```

