#include <iostream>
#include <string>
class MyClass {
public:
  MyClass(std::string s) : str(std::move(s)) { std::cout << "MyClass constructor\n";}
  MyClass(const MyClass& other) : str(other.str){ std::cout << "MyClass copy constructor\n";}
  ~MyClass() { std::cout << "MyClass destructor\n";}
private:
  std::string str;
};
MyClass createObject() {
  std::string temp = "Hello, world!";
  return MyClass(temp);
}
int main() {
  MyClass obj = createObject();
  return 0;
}
